return ['domain'=>'press-permit-core&& (n % 100 < 10 || n % 100 >= 20) ? 1 : 2);&& (n % 100 < 10 || n % 100 >= 20) ? 1: 2);','plural-forms'=>'nplurals=3; plural=(n == 1 ? 0 : n % 10 >= 2 && n % 10 <= 4 && (n % 100 < 10 || n % 100 >= 20) ? 1 : 2);','language'=>'pl_PL(n % 100 < 10 || n % 100 >= 20) ? 1: 2);','project-id-version'=>'PublishPress Permissions Free 4.8.2','pot-creation-date'=>'2026-04-22T11:57:22+00:00','po-revision-date'=>'2026-05-26 19:58+0000','x-generator'=>'WP-CLI 2.12.0','messages'=>['PublishPress Permissions Free'=>'PublishPress Permissions Free','https://publishpress.com/presspermit'=>'https://publishpress.com/presspermit','PublishPress Permissions allows you to enable or deny access to posts, pages, categories, tags and more.'=>'PublishPress Permissions umożliwia włączenie lub zablokowanie dostępu do postów, stron, kategorii, tagów i innych.','PublishPress'=>'PublishPress','https://publishpress.com/'=>'https://publishpress.com/','Edit Tag for All Post Types'=>'Edytuj tag dla wszystkich typów postów','Edit Tag for Posts'=>'Edytuj tag dla postów','Advanced Custom Fields'=>'Zaawansowane pola niestandardowe','Control front-end access to Field Groups with advanced permission management.'=>'Kontroluj dostęp do grup pól na froncie za pomocą zaawansowanego zarządzania uprawnieniami.','Control access to Field Groups'=>'Kontroluj dostęp do grup pól','Front-end visibility restrictions'=>'Ograniczenia widoczności na froncie','Integration with permission groups'=>'Integracja z grupami uprawnień','Beaver Builder'=>'Beaver Builder','Compatibility with Edit Permissions in Beaver Builder.'=>'Kompatybilność z edytowaniem uprawnień w Beaver Builder.','Beaver editor integration'=>'Integracja edytora Beaver','Widget-level permission controls'=>'Kontrola uprawnień na poziomie widgetu','Template access restrictions'=>'Ograniczenia dostępu do szablonów','bbPress Forums'=>'Fora bbPress','Forum-specific permissions for bbPress with detailed control over forum access and participation.'=>'Specyficzne uprawnienia dla forum bbPress z szczegółową kontrolą dostępu i uczestnictwa w forum.','Forum-specific permissions'=>'Specyficzne uprawnienia dla forum','Topic creation restrictions'=>'Ograniczenia tworzenia tematów','Forum access controls'=>'Kontrola dostępu do forum','BuddyPress'=>'BuddyPress','Assign post and term permissions to BuddyPress groups for enhanced content control.'=>'Przypisz uprawnienia do postów i terminów do grup BuddyPress w celu lepszej kontroli treści.','Assign post permissions to BuddyPress groups'=>'Przypisz uprawnienia do postów do grup BuddyPress','Assign term permissions to BuddyPress groups'=>'Przypisz uprawnienia do terminów do grup BuddyPress','Group-based content permissions'=>'Uprawnienia do treści oparte na grupach','CMS Tree View'=>'Widok drzewa CMS','Compatibility with Edit Permissions in CMS Tree View.'=>'Kompatybilność z edytowaniem uprawnień w widoku drzewa CMS.','Permission-aware tree view'=>'Widok drzewa z uwzględnieniem uprawnień','Hierarchical content controls'=>'Hierarchiczne kontrole treści','Elementor'=>'Elementor','Compatibility with Edit Permissions in Elementor.'=>'Kompatybilność z edytowaniem uprawnień w Elementorze.','Elementor editor integration'=>'Integracja edytora Elementor','The Events Calendar'=>'Kalendarz wydarzeń','Apply permission controls to events and event-related content.'=>'Zastosuj kontrole uprawnień do wydarzeń i treści związanych z wydarzeniami.','Event post permissions'=>'Uprawnienia do postów wydarzeń','Event taxonomy controls'=>'Kontrole taksonomii wydarzeń','Nested Pages'=>'Zagnieżdżone strony','Compatibility with Edit Permissions in Nested Pages.'=>'Kompatybilność z edytowaniem uprawnień w zagnieżdżonych stronach.','Permission-aware nested view'=>'Widok z uwzględnieniem uprawnień','Quick edit integration'=>'Integracja szybkiej edycji','PublishPress Statuses'=>'Statusy PublishPress','Compatibility with PublishPress Statuses plugin.'=>'Kompatybilność z wtyczką Statusy PublishPress.','Custom status permissions'=>'Uprawnienia do niestandardowych statusów','Workflow-specific access controls'=>'Kontrola dostępu specyficzna dla przepływu pracy','Status-based editing capabilities'=>'Możliwości edycji oparte na statusie','Relevanssi'=>'Relevanssi','Filter search results based on View Permissions for secure content discovery.'=>'Filtruj wyniki wyszukiwania na podstawie uprawnień widoku w celu bezpiecznego odkrywania treści.','Search result filtering'=>'Filtrowanie wyników wyszukiwania','Permission-aware indexing'=>'Indeksowanie z uwzględnieniem uprawnień','Secure content discovery'=>'Bezpieczne odkrywanie treści','SearchWP'=>'SearchWP','Compatibility with SearchWP term filtering for advanced search capabilities.'=>'Kompatybilność z filtrowaniem terminów SearchWP dla zaawansowanych możliwości wyszukiwania.','Permission-aware search results'=>'Wyniki wyszukiwania z uwzględnieniem uprawnień','Term-based filtering'=>'Filtrowanie oparte na terminach','Advanced search controls'=>'Zaawansowane kontrole wyszukiwania','WooCommerce'=>'WooCommerce','Apply permission controls to WooCommerce products and product categories.'=>'Zastosuj kontrole uprawnień do produktów WooCommerce i kategorii produktów.','Product permissions'=>'Uprawnienia do produktów','Product category controls'=>'Kontrola kategorii produktów','WPML'=>'WPML','Multilingual support with permission synchronization across content translations.'=>'Wsparcie wielojęzyczne z synchronizacją uprawnień w różnych tłumaczeniach treści.','Permission synchronization across translations'=>'Synchronizacja uprawnień w tłumaczeniach','Language-specific content access'=>'Dostęp do treści specyficznych dla języka','Multilingual permission management'=>'Zarządzanie uprawnieniami w wielu językach','Yoast SEO'=>'Yoast SEO','Exclude restricted posts from XML sitemaps to maintain proper SEO indexing.'=>'Wyklucz ograniczone posty z map XML, aby utrzymać właściwe indeksowanie SEO.','Sitemap filtering for restricted content'=>'Filtrowanie mapy witryn dla ograniczonej treści','Search engine visibility controls'=>'Kontrola widoczności w wyszukiwarkach','Permission-aware XML sitemaps'=>'Mapy XML z uwzględnieniem uprawnień','YooTheme'=>'YooTheme','Compatibility with YooTheme builder and term permissions.'=>'Kompatybilność z builderem YooTheme i uprawnieniami terminów.','Builder interface compatibility'=>'Kompatybilność interfejsu buildera','Term permission integration'=>'Integracja uprawnień terminów','Template access controls'=>'Kontrola dostępu do szablonów','Viewing'=>'Podglądanie','Access Circles'=>'Kręgi dostępu','Editing Permissions'=>'Edycja uprawnień','Compatibility Pack'=>'Pakiet kompatybilności','Teaser'=>'Zwiastun','File Access'=>'Dostęp do plików','Membership'=>'Członkostwo','User Posts'=>'Posty użytkowników','Visibility Circles and Editorial Circles block access to content not authored by other group members.'=>'Kręgi widoczności i kręgi redakcyjne blokują dostęp do treści, które nie zostały stworzone przez innych członków grupy.','Post-specific and category-specific permissions for creation and editing.'=>'Uprawnienia specyficzne dla postów oraz kategorii do tworzenia i edytowania.','Integration with ACF, bbPress, BuddyPress, Relevanssi, WPML and other plugins; enhanced Multisite support.'=>'Integracja z ACF, bbPress, BuddyPress, Relevanssi, WPML i innymi wtyczkami; rozszerzone wsparcie dla multisite.','On the site front end, display teaser text for unreadable posts instead of hiding them.'=>'Na froncie strony wyświetl tekst zapowiedzi dla nieczytelnych postów zamiast ich ukrywać.','Restrict direct file requests based on user\'s access to the page a file is attached to.'=>'Ograniczaj bezpośrednie żądania plików w zależności od dostępu użytkownika do strony, do której plik jest dołączony.','Time-limit access customizations by delaying or expiring Permission Group membership.'=>'Dostosuj ograniczenia czasowe dostępu, opóźniając lub wygaszając członkostwo w grupie uprawnień.','Auto-create a page for each user of specified roles. Compatible with several Team / Staff plugins.'=>'Automatycznie twórz stronę dla każdego użytkownika o określonych rolach. Kompatybilne z kilkoma wtyczkami Team / Staff.','Visibility Circles and Editorial Circles block access to content not authored by other group members. Any WP Role, BuddyPress Group or custom Group can be marked as a Circle for specified post types.'=>'Kręgi widoczności i kręgi redakcyjne blokują dostęp do treści, które nie zostały stworzone przez innych członków grupy. Każda rola WP, grupa BuddyPress lub niestandardowa grupa może być oznaczona jako krąg dla określonych typów postów.','Supports content-specific permissions for editing, term assignment and page parent selection. In combination with other modules, supports workflow statuses, PublishPress and PublishPress Revisions.'=>'Obsługuje uprawnienia specyficzne dla treści do edytowania, przypisywania terminów i wyboru rodzica strony. W połączeniu z innymi modułami, obsługuje statusy workflow, PublishPress i PublishPress Revisions.','Adds compatibility or integration with ACF, bbPress, Relevanssi, CMS Tree Page View, Custom Post Type UI, Subscribe2, WPML, various other plugins. Configure any BuddyPress Group as a Permissions Group. For multisite, provides network-wide Permission Groups.'=>'Dodaje zgodność lub integrację z ACF, bbPress, Relevanssi, CMS Tree Page View, Custom Post Type UI, Subscribe2, WPML oraz różnymi innymi wtyczkami. Skonfiguruj dowolną grupę BuddyPress jako grupę uprawnień. Dla multisite zapewnia grupy uprawnień w całej sieci.','On the site front end, replace non-readable content with placeholder text. Can be enabled for any post type. Custom filters are provided but no programming is required for basic usage.'=>'Na froncie strony zastąp nieczytelną treść tekstem zastępczym. Można włączyć dla dowolnego typu postu. Oferowane są niestandardowe filtry, ale nie jest wymagane programowanie do podstawowego użycia.','Filters direct file access, based on user\'s access to post(s) which the file is attached to. No additional configuration required. Creates/modifies .htaccess file in uploads folder (and in main folder for multisite).'=>'Filtruje bezpośredni dostęp do plików, w zależności od dostępu użytkownika do postów, do których plik jest dołączony. Nie wymaga dodatkowej konfiguracji. Tworzy/modyfikuje plik .htaccess w folderze uploads (i w głównym folderze dla multisite).','Allows Permission Group membership to be date-limited (delayed and/or scheduled for expiration). Simple date picker UI alongside group membership selection.'=>'Pozwala na ograniczenie członkostwa w grupie uprawnień do daty (opóźnione i/lub zaplanowane na wygaśnięcie). Prosty interfejs wyboru daty obok wyboru członkostwa w grupie.','Create or synchronize posts to match users. Designed for Team / Staff plugins, but with broad usage potential.'=>'Twórz lub synchronizuj posty, aby pasowały do użytkowników. Zaprojektowane dla wtyczek Team / Staff, ale z szerokim potencjałem zastosowania.','If you like %s, please leave us a %s rating. Thank you!'=>'Jeśli podoba Ci się %s, prosimy o zostawienie nam oceny %s. Dziękujemy!','About PublishPress Permissions'=>'O PublishPress Permissions','About'=>'O programie','Permissions Documentation'=>'Dokumentacja uprawnień','Documentation'=>'Dokumentacja','Contact the PublishPress team'=>'Skontaktuj się z zespołem PublishPress','Contact'=>'Kontakt','Permission Group'=>'Grupa uprawnień','Specific Permissions: restrictions (\'Blocked\') take priority over additions (\'Enabled\')'=>'Specyficzne uprawnienia: ograniczenia (\'Zablokowane\') mają pierwszeństwo przed dodatkami (\'Włączone\')','Specific Permissions: no restrictions (\'Blocked\') can be applied to custom-defined groups'=>'Specyficzne uprawnienia: brak ograniczeń (\'Zablokowane\') może być stosowany do grup zdefiniowanych przez użytkownika','Extra Roles assignment available for {All} and {Anonymous} metagroups'=>'Przypisanie dodatkowych ról dostępne dla metagrup {All} i {Anonymous}','Allow the {All} and {Anonymous} metagroups to be granted specific reading permissions for private content'=>'Zezwól na przyznanie konkretnych uprawnień do odczytu dla prywatnych treści dla metagrup {All} i {Anonymous}','Users who have specific editing permissions for a post or attachment can also delete it'=>'Użytkownicy, którzy mają konkretne uprawnienia do edytowania postu lub załącznika, mogą go również usunąć','Users who have custom editing permissions for an attachment can also delete it'=>'Użytkownicy, którzy mają niestandardowe uprawnienia do edytowania załącznika, mogą go również usunąć','Disable front end filtering if logged user is a content administrator (normally filter to force inclusion of readable private posts in get_pages() listing, post counts, etc.'=>'Wyłącz filtrowanie na froncie, jeśli zalogowany użytkownik jest administratorem treści (normalnie filtr, aby wymusić uwzględnienie czytelnych prywatnych postów w liście get_pages(), liczby postów itp.','Disable front end filtering for all users (subject to limitation by PP_UNFILTERED_FRONT_TYPES)'=>'Wyłącz filtrowanie na froncie dla wszystkich użytkowników (podlega ograniczeniom przez PP_UNFILTERED_FRONT_TYPES)','Comma-separated list of post types to limit the effect of PP_UNFILTERED_FRONT and apply_filters( \'presspermit_skip_cap_filtering\' )'=>'Lista typów postów oddzielona przecinkami, aby ograniczyć działanie PP_UNFILTERED_FRONT i apply_filters( \'presspermit_skip_cap_filtering\' )','Specific Permissions: additions (\'Enabled\') are not applied, cannot be assigned'=>'Specyficzne uprawnienia: dodatki (\'Włączone\') nie są stosowane, nie mogą być przypisane','Don\'t assign or apply specific permissions for the \'post\' type'=>'Nie przypisuj ani nie stosuj specyficznych uprawnień dla typu \'post\'','Don\'t assign or apply specific permissions for the \'page\' type'=>'Nie przypisuj ani nie stosuj specyficznych uprawnień dla typu \'page\'','Don\'t assign or apply specific permissions for the \'media\' type'=>'Nie przypisuj ani nie stosuj specyficznych uprawnień dla typu \'media\'','Don\'t assign or apply specific permissions for the specified custom post type'=>'Nie przypisuj ani nie stosuj specyficznych uprawnień dla określonego niestandardowego typu postu','Include scheduled posts in the posts query if user can edit them'=>'Uwzględnij zaplanowane posty w zapytaniu o posty, jeśli użytkownik może je edytować','Don\'t filter term post counts in get_terms() call'=>'Nie filtruj liczby postów terminu w wywołaniu get_terms()','Leave unreadable posts on WP Navigation Menus'=>'Zostaw nieczytelne posty w menu nawigacyjnym WP','Don\'t apply CSS to hide empty Nav Menus'=>'Nie stosuj CSS do ukrywania pustych menu nawigacyjnych','For legacy Nav Menus, hide empty nav menu div'=>'Dla starszych menu nawigacyjnych, ukryj pusty div menu nawigacyjnego','Leave terms with no readable posts on WP Navigation Menus'=>'Zostaw terminy bez czytelnych postów w menu nawigacyjnym WP','When Teaser is applied with Redirect enabled, append original url as redirect_to argument'=>'Gdy Teaser jest stosowany z włączonym przekierowaniem, dołącz oryginalny URL jako argument redirect_to','For Teaser compatibility, specify a redirect argument to use instead of redirect_to'=>'Dla zgodności z Teaserem, określ argument przekierowania do użycia zamiast redirect_to','For Teaser compatibility, specify an additional redirect argument other than redirect_to'=>'Dla zgodności z Teaserem, określ dodatkowy argument przekierowania, inny niż redirect_to','For Teaser compatibility, prevent the pp_permissions argument from being appended to redirects'=>'Dla zgodności z Teaserem, zapobiegaj dołączaniu argumentu pp_permissions do przekierowań','Filter priority for \'get_pages\' filter (default: 1)'=>'Priorytet filtra dla filtra \'get_pages\' (domyślnie: 1)','Don\'t include readable private pages in the Pages widget or other wp_list_pages() / get_pages() results    '=>'Nie uwzględniaj czytelnych prywatnych stron w widżecie Strony ani w innych wynikach wp_list_pages() / get_pages()    ','If some pages have been suppressed from get_pages() results, change child pages\' corresponding post_parent values to a visible ancestor'=>'Jeśli niektóre strony zostały ukryte w wynikach get_pages(), zmień odpowiadające wartości post_parent dla stron podrzędnych na widocznego przodka','Never modify the post_parent value in the get_pages() result set, even if some pages have been suppressed'=>'Nigdy nie modyfikuj wartości post_parent w zestawie wyników get_pages(), nawet jeśli niektóre strony zostały ukryte','For performance, change the get_pages() database query to return only a subset of fields, excluding post_content'=>'Aby poprawić wydajność, zmień zapytanie bazy danych get_pages(), aby zwracało tylko podzbiór pól, wykluczając post_content','Don\'t apply content teaser to get_pages() results (leave unreadable posts hidden)'=>'Nie stosuj teasera treści do wyników get_pages() (pozostaw nieczytelne posty ukryte)','If some terms have been suppressed from get_terms() results, change child terms\' corresponding parent values to a visible ancestor'=>'Jeśli niektóre terminy zostały ukryte w wynikach get_terms(), zmień odpowiadające wartości rodzica dla terminów podrzędnych na widocznego przodka','Never modify the parent value in the get_terms() result set, even if some terms have been suppressed'=>'Nigdy nie modyfikuj wartości rodzica w zestawie wyników get_terms(), nawet jeśli niektóre terminy zostały ukryte','Set Author to current user if autoset_post_author / autoset_page_author capability is assigned'=>'Ustaw autora na bieżącego użytkownika, jeśli przypisano uprawnienia autoset_post_author / autoset_page_author','Leave Media Library with normal access criteria based on user\'s role capabilities '=>'Zostaw Media Library z normalnymi kryteriami dostępu opartymi na możliwościach roli użytkownika ','Accommodate front end uploading solutions that require page editing capabilities for the async upload request'=>'Dostosuj rozwiązania do przesyłania z front-endu, które wymagają możliwości edytowania stron dla asynchronicznego żądania przesyłania','Treat media attached to unregistered post types as unattached, to avoid improper and confusing filtering'=>'Traktuj media dołączone do niezarejestrowanych typów postów jako nieprzyłączone, aby uniknąć niewłaściwego i mylącego filtrowania','Attached Files Private setting available'=>'Ustawienie prywatne dla dołączonych plików dostępne','Comma-separated list of mime types to exclude from File Access filtering'=>'Lista typów mime oddzielonych przecinkami do wykluczenia z filtrowania dostępu do plików','Comma-separated list of mime types to include in File Access filtering (bypassing others)'=>'Lista typów mime oddzielona przecinkami, które należy uwzględnić w filtrowaniu dostępu do plików (omijając inne)','When file access is blocked, do not set the WP_Query 404 / 403 property'=>'Gdy dostęp do pliku jest zablokowany, nie ustawiaj właściwości 404 / 403 w WP_Query','HTTP status code to send when file access is blocked'=>'Kod statusu HTTP do wysłania, gdy dostęp do pliku jest zablokowany','On Users listing, Permission groups in custom column are list filter links instead of group edit links'=>'Na liście użytkowników grupy uprawnień w niestandardowej kolumnie są linkami filtrującymi zamiast linków do edytowania grup','Unlock Permissions > Settings > Core > Admin Back End > \'Hide non-editable posts\''=>'Odblokuj Uprawnienia > Ustawienia > Podstawowe > Admin Back End > \'Ukryj posty, które nie mogą być edytowane\'','Within the async-upload.php script, filter author\'s retrieval of the attachment they just uploaded'=>'W skrypcie async-upload.php, filtruj pobieranie autora załącznika, który właśnie przesłano','Don\'t filter comment display or moderation within wp-admin'=>'Nie filtruj wyświetlania komentarzy ani moderacji w wp-admin','Allow Administrators to be added to Permission Groups, even though they are not restricted'=>'Pozwól na dodawanie administratorów do grup uprawnień, nawet jeśli nie są ograniczeni','If propagating permissions are assigned to a page branch, overwrite any explicitly assigned permissions in sub-pages'=>'Jeśli przypisano propagujące uprawnienia do gałęzi strony, nadpisz wszelkie wyraźnie przypisane uprawnienia w podstronach','Max number of specific permissions to insert in a single database query (default 1000)'=>'Maksymalna liczba specyficznych uprawnień do wstawienia w jednym zapytaniu do bazy danych (domyślnie 1000)','Don\'t tweak the admin menu indexes to position Permissions menu under Users'=>'Nie zmieniaj indeksów menu administratora, aby umieścić menu Uprawnienia pod Użytkownikami','Don\'t add a Permissions menu. Instead, add menu items to the Users and Settings menus.'=>'Nie dodawaj menu Uprawnienia. Zamiast tego, dodaj elementy menu do menu Użytkownicy i Ustawienia.','Customize Permissions screen title for Groups'=>'Dostosuj tytuł ekranu Uprawnień dla Grup','Customize Permission Groups caption on user profile'=>'Dostosuj podpis grup uprawnień na profilu użytkownika','Only one group is selectable on Add User screen'=>'Tylko jedna grupa jest wybieralna na ekranie Dodaj użytkownika','Only one group is selectable on Edit User screen'=>'Tylko jedna grupa jest wybieralna na ekranie Edytuj użytkownika','Display a custom hint on Permissions > User Groups'=>'Wyświetl niestandardową podpowiedź w Uprawnieniach > Grupy użytkowników','Max number of non-hierarchical posts / terms to display at one time (per page)'=>'Maksymalna liczba niehierarchicznych postów / terminów do wyświetlenia jednocześnie (na stronę)','Max number of hierarchical posts / terms to display at one time (per page)'=>'Maksymalna liczba hierarchicznych postów / terminów do wyświetlenia jednocześnie (na stronie)','Disable auto-determination of how many levels of page tree to make visble by default. Instead, use specified value.'=>'Wyłącz automatyczne określanie, ile poziomów drzewa stron ma być widocznych domyślnie. Zamiast tego użyj określonej wartości.','Target number of visible pages/terms, used for auto-determination of number of visible levels'=>'Docelowa liczba widocznych stron/terminów, używana do automatycznego określania liczby widocznych poziomów','Make search function on the post selection metabox look at post content'=>'Spraw, aby funkcja wyszukiwania w metaboxie wyboru postów przeszukiwała treść postu','Make search function on the post selection metabox look at post excerpt'=>'Spraw, aby funkcja wyszukiwania w metaboxie wyboru postów przeszukiwała fragment postu','Search by last name instead of display name'=>'Szukaj po nazwisku zamiast po nazwie wyświetlanej','User field to search by default'=>'Pole użytkownika do wyszukiwania domyślnie','User meta fields selectable for search (comma-separated)'=>'Pola meta użytkownika wybieralne do wyszukiwania (oddzielone przecinkami)','User meta fields which should be treated as numeric (comma-separated)'=>'Pola meta użytkownika, które powinny być traktowane jako numeryczne (oddzielone przecinkami)','User meta fields which should be treated as boolean (comma-separated)'=>'Pola meta użytkownika, które powinny być traktowane jako logiczne (oddzielone przecinkami)','Use display name for search results instead of user_login'=>'Użyj nazwy wyświetlanej dla wyników wyszukiwania zamiast user_login','When synchronizing role metagroups to currently defined WP roles, don\'t delete groups for previously defined WP roles.'=>'Podczas synchronizacji metagrup ról do obecnie zdefiniowanych ról WP, nie usuwaj grup dla wcześniej zdefiniowanych ról WP.','Force detection of WP user roles which are appended dynamically but not stored to the WP database.'=>'Wymuś wykrywanie ról użytkowników WP, które są dodawane dynamicznie, ale nie są przechowywane w bazie danych WP.','To save memory on front end access, don\'t register any filters related to content editing'=>'Aby zaoszczędzić 